@Component
public class ProblemWriter {
  private final JsonMapper json;

  public ProblemWriter(JsonMapper json) {
    this.json = json;
  }

  public static ProblemDetail problem(HttpServletRequest request, HttpStatus status, String type,
                    String title, String detail) {
    ProblemDetail p = ProblemDetail.forStatusAndDetail(status, detail);
    p.setType(URI.create("https://roombook.example/problems/" + type));
    p.setTitle(title);
    p.setInstance(URI.create(request.getRequestURI()));
    p.setProperty("requestId", MDC.get("requestId"));
    return p;
  }

  public void write(HttpServletResponse response, ProblemDetail problem) throws IOException {
    response.setStatus(problem.getStatus());
    response.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
    json.writeValue(response.getOutputStream(), problem);
  }

  public AuthenticationEntryPoint entryPoint() {
    return (request, response, e) -> {
      response.setHeader("WWW-Authenticate", "Bearer realm=\"roombook\"");
      write(response, problem(request, HttpStatus.UNAUTHORIZED, "unauthorized",
          "Authentication required", "Sign in to continue."));
    };
  }

