import java.util.Map;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.DelegatingPasswordEncoder;

void main() {
  var encoder = new DelegatingPasswordEncoder("argon2", Map.of(
      "argon2", new Argon2PasswordEncoder(16, 32, 4, 65_536, 3),
      "bcrypt", new BCryptPasswordEncoder()));

  String stored = encoder.encode("correct horse battery staple");
  IO.println(stored);
  IO.println(encoder.encode("correct horse battery staple"));
  IO.println(encoder.matches("correct horse battery staple", stored));
  IO.println(encoder.matches("Correct horse battery staple", stored));

  String old = "{bcrypt}" + new BCryptPasswordEncoder().encode("correct horse battery staple");
  IO.println(encoder.upgradeEncoding(stored) + " " + encoder.upgradeEncoding(old));
}

