  @Override
  public UserDetails loadUserByUsername(String email) {
    UserRow user = users.findByEmail(email.strip())
        .filter(u -> u.passwordHash() != null)
        .orElseThrow(() -> new UsernameNotFoundException(email));
    return User.withUsername(user.email())
        .password(user.passwordHash())
        .authorities(List.of())
        .build();
  }

  @Override
  public UserDetails updatePassword(UserDetails user, String newHash) {
    users.findByEmail(user.getUsername()).ifPresent(u -> users.updatePasswordHash(u.id(), newHash));
    return User.withUserDetails(user).password(newHash).build();
  }

private UserRow checkPassword(Credentials body) {
  authenticationManager.authenticate(
      UsernamePasswordAuthenticationToken.unauthenticated(body.email().strip(), body.password()));
  return users.findByEmail(body.email().strip()).orElseThrow(() -> new BadCredentialsException("gone"));
}

private void startSession(UserRow user, HttpServletRequest request, HttpServletResponse response) {
  var auth = new RoombookAuthentication(
      Roles.user("session", user.id(), user.role(), user.buildingId(), null));
  fixation.onAuthentication(auth, request, response);
  SecurityContext context = SecurityContextHolder.createEmptyContext();
  context.setAuthentication(auth);
  SecurityContextHolder.setContext(context);
  contexts.saveContext(context, request, response);
}

@PostMapping("/auth/login")
UserView logIn(@Valid @RequestBody Credentials body,
       HttpServletRequest request, HttpServletResponse response) {
  UserRow user = checkPassword(body);
  startSession(user, request, response);
  return UserView.of(user);
}

@Bean
@Order(1)
SecurityFilterChain tokenChain(HttpSecurity http, ApiKeyFilter apiKeys, ProblemWriter problems) throws Exception {
  http.securityMatcher(request -> request.getHeader("Authorization") != null
          || request.getHeader("Api-Key") != null)
      .authorizeHttpRequests(SecurityConfig::rules)
      .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
      .csrf(csrf -> csrf.disable())
      // ...
  return http.build();
}

@Bean
@Order(2)
SecurityFilterChain browserChain(HttpSecurity http, ProblemWriter problems) throws Exception {
  http.authorizeHttpRequests(SecurityConfig::rules)
      .requestCache(cache -> cache.disable())
      .csrf(csrf -> csrf.spa().ignoringRequestMatchers("/v1/auth/token", "/v1/auth/token/refresh"))
      .logout(logout -> logout.logoutUrl("/v1/auth/logout")
          .logoutSuccessHandler(new HttpStatusReturningLogoutSuccessHandler(HttpStatus.NO_CONTENT)))
      .exceptionHandling(e -> e.authenticationEntryPoint(problems.entryPoint())
          .accessDeniedHandler(problems.accessDenied()));
  return http.build();
}

