  @Bean
  JwtDecoder jwtDecoder(SecretKey jwtKey) {
    NimbusJwtDecoder decoder = NimbusJwtDecoder.withSecretKey(jwtKey).macAlgorithm(MacAlgorithm.HS256).build();
    decoder.setJwtValidator(JwtValidators.createDefaultWithValidators(List.of(
        new org.springframework.security.oauth2.jwt.JwtIssuerValidator(AccessTokens.ISSUER),
        new JwtAudienceValidator(AccessTokens.AUDIENCE))));
    return decoder;
  }

